const fetchItem = (id) =>
  new Promise((resolve) => setTimeout(() => resolve({ id }), 100));

async function loadItems(ids) {
  const results = [];
  ids.forEach(async (id) => {
    const item = await fetchItem(id);
    results.push(item);
  });
  return results;
}

const items = await loadItems([1, 2, 3]);
console.log(items.length); // 0

explanation:
`Array.prototype.forEach` calls the callback for each element and **ignores its return value**. An `async` function always returns a promise, so each call:

- runs synchronously until its first `await` (starting `fetchItem(id)`),
- then returns a pending promise, which `forEach` discards.

So all three fetches start right away and run concurrently, `forEach` returns `undefined`, and `loadItems` immediately returns `results` while it is still empty. `await loadItems(...)` waits only for that returned promise, not for the fetches, so the log prints `0`. About 100 ms later the callbacks resume and push their items into the same array (it would then have length 3), but the log has already happened.

Use a construct that actually waits for the promises:

```js
// Option 1, sequential: one fetch at a time (about 300 ms total here)
const results = [];
for (const id of ids) {
  results.push(await fetchItem(id));
}

// Option 2, parallel: start all, wait for all (about 100 ms total here)
const results = await Promise.all(ids.map((id) => fetchItem(id)));
```

`Promise.all` also keeps results in the order of `ids`, even if the fetches finish in a different order.

