  new Promise((resolve, reject) => {
    setTimeout(() => {
      console.log('settled ' + value);
      if (fail) reject(value);
      else resolve(value);
    }, ms);
  });

Promise.all([wait(30, 'a'), wait(10, 'b', true), wait(20, 'c')])
  .then((values) => console.log('got ' + values))
  .catch((err) => console.log('caught ' + err));

function fetchUser(id) {
  return fetch(`/api/users/${id}`).then((res) => {
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  });
}

async function loadUser(id) {
  try {
    return fetchUser(id);
  } catch (err) {
    console.warn('Falling back to guest', err);
    return { id, name: 'Guest' };
  }
}

loadUser(42).then((user) => render(user));

explanation:
A `try`/`catch` only catches exceptions thrown while execution is inside the `try` block. `return fetchUser(id)` evaluates `fetchUser(id)`, which doesn't throw: it immediately returns a pending promise. The `return` then completes the `try` block normally (a `finally` block would run at this point), and the `catch` is never consulted.

An async function's promise is resolved with whatever it returns. When that value is a promise, `loadUser`'s promise follows it, so when the request later fails, `loadUser(42)` rejects with `Error: HTTP 500`. The caller only passes a fulfillment handler to `.then()`, so nothing handles the rejection and it is reported as unhandled.

With `return await fetchUser(id)`, the function pauses **inside** the `try`. When the promise rejects, `await` throws the rejection reason at that point, the `catch` runs, and `loadUser` fulfills with the guest object:

```js
async function loadUser(id) {
  try {
    return await fetchUser(id);
  } catch (err) {
    console.warn('Falling back to guest', err);
    return { id, name: 'Guest' };
  }
}
```

Outside a `try`/`catch`/`finally`, `return promise` and `return await promise` settle the async function's promise with the same result (only the timing differs slightly). Inside a `try` block, `return await` is required if you want the `catch` or `finally` to see the outcome of the promise.

